steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(first: 50, filter: { dueDate: { before: \"2027-01-01T00:00:00.000Z\" } }) { nodes { id name description priority state { name } milestone { name id } dueDate } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ __type(name: \"Project\") { fields { name type { name kind ofType { name } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ health: __type(name: \"ProjectUpdateHealthType\") { enumValues { name } } milestone: __type(name: \"ProjectMilestone\") { fields { name type { name kind } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ projects(first: 50) { nodes { id name description priority priorityLabel health projectMilestones(first: 10) { nodes { id name targetDate description } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ __type(name: \"Query\") { fields { name args { name type { name kind ofType { name } } } } } }"
  }' | python3 -c "import sys,json; data=json.load(sys.stdin); fields=[f for f in data['data']['__type']['fields'] if 'project' in f['name'].lower()]; print(json.dumps(fields, indent=2))"

