curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ projects(first: 50) { nodes { id name description priority priorityLabel health projectMilestones(first: 10) { nodes { id name targetDate } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ __type(name: \"ProjectFilter\") { inputFields { name type { name kind ofType { name } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ projectMilestones(first: 50, filter: { name: { contains: \"Meridian\" } }) { nodes { id name targetDate project { id name description priority priorityLabel health } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ atlas: project(id: \"p-atlas\") { id name description priority priorityLabel health teams { nodes { id name } } } summit: project(id: \"p-summit\") { id name description priority priorityLabel health teams { nodes { id name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ projectMilestones(first: 50, filter: { name: { contains: \"Meridian\" }, targetDate: { equals: \"2026-12-02\" } }) { nodes { id name targetDate project { id name slugId description priority priorityLabel health state } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ projectMilestones(first: 50, filter: { name: { contains: \"Meridian\" }, targetDate: { eq: \"2026-12-02\" } }) { nodes { id name targetDate project { id name slugId description priority priorityLabel health state } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ atlas: project(id: \"p-atlas\") { id name slugId description priority priorityLabel health state startDate targetDate lead { name } teams { nodes { name } } members { nodes { name } } } summit: project(id: \"p-summit\") { id name slugId description priority priorityLabel health state startDate targetDate lead { name } teams { nodes { name } } members { nodes { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ projects(first: 50, filter: { name: { contains: \"Atlas\" } }) { nodes { id name slugId description priority priorityLabel health state startDate targetDate lead { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ atlas: searchProjects(term: \"Atlas\", first: 10) { nodes { id name description priority priorityLabel health state } } summit: searchProjects(term: \"Summit\", first: 10) { nodes { id name description priority priorityLabel health state } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ atlas: searchProjects(term: \"Atlas\", first: 1) { nodes { id name description priority priorityLabel health state startDate targetDate } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ m1: projectMilestone(id: \"m-ms1\") { id name description targetDate project { id name slugId url } } m2: projectMilestone(id: \"m-ms2\") { id name description targetDate project { id name slugId url } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name } } } } } }"
  }' | python3 -c "import sys,json; data=json.load(sys.stdin); fields=[f for f in data['data']['__type']['fields'] if 'project' in f['name'].lower()]; print(json.dumps(fields, indent=2))"

